import { pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Better Auth tables (`users`, `sessions`, `accounts`, `verifications`) are
 * generated by the Better Auth CLI into `./auth-schema.ts` and re-exported
 * here so drizzle-kit — pointed at this file by `drizzle.config.ts` — picks
 * them up in the regular migration pipeline (VISION §6.7). Never hand-edit
 * `auth-schema.ts`; regenerate it (see `better-auth.config.ts`) instead.
 */
export * from "./auth-schema";

/**
 * A household — the top-level tenant every other entity belongs to (VISION
 * §5). MVP: a user belongs to a single household.
 */
export const households = pgTable("households", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: text("name").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});
